# Small renderer for the fixed authoring vocabulary above; no third-party dependencies.
from html.parser import HTMLParser
import re
class Node:
 def __init__(self, tag='', attrs=None): self.tag=tag; self.attrs=dict(attrs or []); self.children=[]
class Parser(HTMLParser):
 def __init__(self):
  super().__init__(convert_charrefs=True); self.root=Node(); self.stack=[self.root]
 def handle_starttag(self,tag,attrs):
  n=Node(tag,attrs); self.stack[-1].children.append(n)
  if tag not in ['br','hr','img','meta','link','input']: self.stack.append(n)
 def handle_endtag(self,tag):
  if len(self.stack)>1 and self.stack[-1].tag==tag: self.stack.pop()
 def handle_data(self,data): self.stack[-1].children.append(data)
def descendants(n,tag):
 if isinstance(n,str): return []
 return ([n] if n.tag==tag else [])+[x for c in n.children for x in descendants(c,tag)]
def plain(n): return n if isinstance(n,str) else ''.join(plain(c) for c in n.children)
def render(n):
 if isinstance(n,str): return n
 text=''.join(render(c) for c in n.children)
 if n.tag=='p': return text.strip()+'\n\n'
 if n.tag=='strong': return '**'+text+'**'
 if n.tag=='em': return '*'+text+'*'
 if n.tag=='pre': return '```text\n'+plain(n).strip()+'\n```\n\n'
 if n.tag=='code': return '`'+text+'`'
 if n.tag=='a': return '['+text+']('+n.attrs['href']+')'
 if n.tag=='table':
  rows=[]
  for tr in descendants(n,'tr'):
   rows.append([render(c).strip().replace('|','\\|').replace('\n',' ') for c in tr.children if not isinstance(c,str) and c.tag in ['th','td']])
  return '\n'.join(['| '+' | '.join(rows[0])+' |','| '+' | '.join(['---']*len(rows[0]))+' |']+['| '+' | '.join(r)+' |' for r in rows[1:]])+'\n\n'
 if n.tag=='figure':
  labels=[plain(t) for t in descendants(n,'text')]; cap=plain(descendants(n,'figcaption')[0])
  if cap.startswith('Различие миров'):
   graph='flowchart LR\n  W1["w₁: P истинно"] -->|доступен| W1\n  W1 -->|доступен| W2["w₂: P ложно"]'
  else:
   graph='flowchart LR\n'+'\n'.join(f'  N{i}["{labels[2*i]}<br/>{labels[2*i+1]}"]' for i in range(len(labels)//2))
   if not cap.startswith('Три разных контракта'):
    graph+='\n'+'\n'.join(f'  N{i} --> N{i+1}' for i in range(len(labels)//2-1))
  return '```mermaid\n'+graph+'\n```\n\n*'+cap+'*\n\n'
 if n.tag=='div' and n.attrs.get('class')=='note':
  return '> [!note]\n'+'\n'.join('> '+line if line else '>' for line in text.strip().splitlines())+'\n\n'
 return text

def md(html):
 parser=Parser(); parser.feed(html)
 return re.sub(r'\n{3,}', '\n\n', render(parser.root)).strip()
def fname(i): return f'{i:02d}-{LESSONS[i-1]["slug"]}.md'
def link(i,label=None): return f'[{label or LESSONS[i-1]["title"]}]({fname(i)})'
def callout(title,body,kind='answer'):
 return f'> [!{kind}]- {title}\n'+'\n'.join('> '+line if line else '>' for line in body.strip().splitlines())+'\n'
def source_lines(keys): return '\n'.join('- ['+SOURCES[k][0]+']('+SOURCES[k][1]+')' for k in dict.fromkeys(keys))

def build():
 assert len(LESSONS)==12
 manifest=[]
 for i,L in enumerate(LESSONS,1):
  prereq='Предварительная подготовка не нужна.' if i==1 else 'Перед началом: '+link(i-1,f'урок {i-1}')+'.'
  nav=('← '+link(i-1,f'Урок {i-1}')+' · ' if i>1 else '')+'[Оглавление](00-index.md) · '+(link(i+1,f'Урок {i+1}')+' →' if i<12 else '[Практикум](13-practice.md) →')
  out=f'---\ntags:\n  - логика\n  - обучение\nlesson: {i}\n---\n\n# {i:02d}. {L["title"]}\n\nУрок {i} из 12 · ориентир: 45–75 минут вместе с задачами.\n\n{nav}\n\n{prereq}\n\n{L["lead"]}\n\n## В этом уроке\n\n'
  for j,(title,body) in enumerate(L['sections'],1): out+=f'- [{j}. {title}](#раздел-{j})\n'
  out+='- [Задачи и самопроверка](#задачи-и-самопроверка)\n\n'
  for j,(title,body) in enumerate(L['sections'],1):
   # Explicit Obsidian-compatible headings make anchors portable and predictable.
   out+=f'## Раздел {j}\n\n### {title}\n\n{md(body)}\n\n'
  out+='## Задачи и самопроверка\n\nСначала запиши свой ответ. Затем раскрой разбор и сравни именно ход решения.\n\n'
  for j,(task,answer) in enumerate(L['exercises'],1):
   out+=f'### Задача {j}\n\n{task}\n\n'+callout('Разбор',answer)+'\n'
  out+='Дополнительная практика: [задание '+str(i)+'](13-practice.md#задание-'+str(i)+').\n\n## Что теперь должно получаться\n\n'
  out+='\n'.join('- [ ] '+t for t in L['takeaways'])+'\n\n## Источники и дальнейшее чтение\n\n'+source_lines(L['sources'])
  out+='\n\nОпределения сверены по указанным источникам. Примеры, вычисления и задачи составлены для этого курса; это не перевод учебника.\n\n'+nav+'\n'
  (ROOT/fname(i)).write_text(out)
  manifest.append(dict(number=i,file=fname(i),title=L['title'],sections=5,exercises=2,practice=i,sources=L['sources']))
 parts=[('I. Основы рассуждения',range(1,4)),('II. Доказательства и язык правил',range(4,7)),('III. Неполные и противоречивые сведения',range(7,10)),('IV. Основания знания и пересмотр',range(10,13))]
 index='''---
tags:
  - логика
  - курс
---

# Логика: от основ к эпистемологии агента

12 последовательных уроков на русском для программиста без специальной подготовки по логике. Цель — научиться читать определения, строить доказательства и контрмодели, а затем проверять точные положения собственной системы памяти.

Это вводный маршрут, а не обещание освоить всю математическую логику. Для уроков 1–6 достаточно бумаги. В уроке 7 есть необязательные примеры для SWI-Prolog. Нейросеть и платные API для упражнений не нужны.

## Как заниматься

1. Проходи по порядку: определения предыдущего урока используются в следующем.
2. Отведи ориентировочно 45–75 минут на урок с задачами; сложный раздел можно разделить на два занятия.
3. Прежде чем раскрыть решение, запиши собственный ответ и его основание.
4. Если ошибся, обозначь место: перевод, правило, модель, поиск или политика действия.
5. Через день повтори задачу без подсказки. Темп важнее скорости прохождения.

В комплекте 24 задачи внутри уроков и 13 заданий общего практикума, включая итоговый разбор нашей эпистемической политики. Решения свёрнуты стандартными callout-блоками Obsidian. Чекбоксы отмечаются вручную.

'''
 for name,ids in parts:
  index+='## Часть '+name+'\n\n'
  for i in ids: index+=f'- **{i:02d}. '+link(i)+'** — '+LESSONS[i-1]['lead']+'\n'
  index+='\n'
 index+='''## Приложения

- [Практикум и карта покрытия](13-practice.md)
- [Словарь обозначений и различий](14-glossary.md)
- [Источники и маршрут дальнейшего чтения](15-sources.md)
- [Учебная программа Prolog](examples/prolog-basics.pl)

## Как открыть в Obsidian

Скопируй целиком эту папку в своё хранилище или открой её как отдельное хранилище. Начни с `00-index.md`. Используются обычные Markdown-ссылки, встроенные callout-блоки и Mermaid; сторонние плагины не нужны. Если диаграмма не отображается в другом редакторе, её смысл также объяснён соседним текстом.

Материалы сверены 10 сентября 2026 года. Поведение примеров проверено установленным SWI-Prolog; версия и границы проверок указаны в `verification.md`. Различия между общими логиками и текущей политикой проекта отмечены в уроках 7, 9 и 12.
'''
 (ROOT/'00-index.md').write_text(index)
 practice='# Практикум по логике\n\n[Оглавление](00-index.md) · '+link(12,'Последний урок')+'\n\n13 заданий: сначала самостоятельная попытка, затем подсказка и разбор. Критерии проверяют рассуждение, а не совпадение формулировок.\n\n## Карта покрытия\n\n| Урок | Тема | Закрепление |\n| --- | --- | --- |\n'
 for i,L in enumerate(LESSONS,1):
  tasks=[str(j) for j,E in enumerate(PRACTICE,1) if i in E[1]]
  practice+='| '+link(i,str(i))+' | '+L['title']+' | '+', '.join(f'[№ {j}](#задание-{j})' for j in tasks)+' |\n'
 for j,(title,ids,task,hint,criteria,answer) in enumerate(PRACTICE,1):
  difficulty='базовое' if j<=5 else 'среднее' if j<=11 else 'итоговое'
  practice+=f'\n## Задание {j}\n\n### {title}\n\nУровень: {difficulty}. Закрепляет: '+', '.join(link(i,f'урок {i}') for i in ids)+'.\n\n'+task+'\n\n**Готово, когда:** '+criteria+'\n\n'+callout('Подсказка',hint,'hint')+'\n'+callout('Разбор решения',answer)+'\n'
 practice+='\n[Вернуться к оглавлению](00-index.md)\n'
 (ROOT/'13-practice.md').write_text(practice)
 (ROOT/'course-manifest.json').write_text(json.dumps(dict(language='ru',format='Obsidian Markdown',lessons=manifest,lesson_exercises=24,practice_exercises=13,source_checked_on='2026-09-10'),ensure_ascii=False,indent=2)+'\n')

def protect_markdown_backslashes():
 for file in ROOT.glob('*.md'):
  lines=[]; fenced=False
  for line in file.read_text().splitlines():
   if line.startswith('```'): fenced=not fenced
   if not fenced and not line.startswith('```'):
    parts=re.split(r'(`[^`]*`)',line)
    for k in range(0,len(parts),2):
     parts[k]=re.sub(r'(?<!\\)\\\+', lambda m: '\\\\+',parts[k])
    line=''.join(parts)
   lines.append(line)
  file.write_text('\n'.join(lines)+'\n')

if __name__=='__main__':
 build()
 protect_markdown_backslashes()

